-- The DOVE IQ GRIP code key (Code keys -> Parting -> DOVE IQ GRIP), from the
-- ISCAR e-catalog's DOVE IQ GRIP families (TIGER-IQ inserts, THDR/L-IQ holders,
-- CR THDN-IQ cartridges); kept if one exists.
INSERT INTO "AppSetting" ("key", "value") VALUES ('codekey.doveiqgrip', $ck${"title": "DOVE IQ GRIP code key – inserts and tools", "subtitle": "Wide single-ended utility inserts (TIGER-IQ) for external heavy grooving and deep machining, their THDR/L-IQ holders and CR THDN-IQ cartridges", "example": "TIGER 1008Y-IQ", "decoder": "dove-iq-grip", "sections": [{"key": "i-family", "title": "Insert – family", "sample": "TIGER", "rows": [{"code": "TIGER", "meaning": "Utility single-ended insert for external heavy grooving and deep machining"}]}, {"key": "i-width", "title": "Insert – width and corner radius", "sample": "1008", "rows": [{"code": "####", "meaning": "Width (first two digits) and corner radius x10 (e.g. 1008 = 10 mm, R0.8; 2020 = 20 mm, R2.0)"}]}, {"key": "i-chip", "title": "Chipformer", "sample": "Y", "rows": [{"code": "Y", "meaning": "Utility chipformer for heavy grooving (inferred)"}]}, {"key": "i-variant", "title": "Insert – variant", "rows": [{"code": "CW", "meaning": "CW version (see the catalog) (inferred)"}]}, {"key": "i-iq", "title": "Insert – IQ line", "sample": "IQ", "rows": [{"code": "IQ", "meaning": "DOVE IQ GRIP dovetail clamping (THDR/L-IQ holders)"}]}, {"key": "t-family", "title": "Tool – family", "rows": [{"code": "THD", "meaning": "External holders for wide grooving inserts (THDR / THDL)"}, {"code": "CR THD", "meaning": "Cartridges for blades carrying wide grooving inserts (CR THDN)"}]}, {"key": "t-hand", "title": "Tool – hand", "rows": [{"code": "R", "meaning": "Right-hand"}, {"code": "L", "meaning": "Left-hand"}, {"code": "N", "meaning": "Neutral"}]}, {"key": "t-height", "title": "Tool – shank", "rows": [{"code": "####", "meaning": "Shank height x width (e.g. 2525 = 25 x 25 mm)"}]}, {"key": "t-width", "title": "Tool – insert width", "rows": [{"code": "##", "meaning": "Insert width in mm (10 – 20)"}]}, {"key": "t-suffix", "title": "Tool – suffixes", "rows": [{"code": "T##", "meaning": "Maximum cutting depth in mm (e.g. T20, T40, T50)"}, {"code": "IQ", "meaning": "IQ line (DOVE IQ GRIP)"}]}]}$ck$)
ON CONFLICT ("key") DO NOTHING;
